START TRANSACTION;

-- ---------------------------------------------------------------------
-- Descripción general (sede, fechas, formato, turnos de salida)
-- ---------------------------------------------------------------------
INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled) VALUES
(362, 'descripcion', 'generic', 'Descripción',
'{"text": "TORNEO ANUAL 2026 — CLUB DE GOLF SANTA ANITA, Guadalajara, Jalisco.\\nDel 9 al 14 de noviembre de 2026.\\n\\nFormato: 54 hoyos en tres rondas de competencia.\\n· Categorías Campeonato, AA, A, B y C: STROKE PLAY sin hándicap índice.\\n· Categoría D: 80% de hándicap en formato STABLEFORD.\\n· Categorías Damas y Senior: 80% de hándicap en formato STROKE PLAY.\\n\\nSalidas por horario: primer turno a partir de las 6:50 a.m. y segundo turno a partir de las 11:00 a.m.\\n\\nInscripciones y reservaciones: https://santaanita.speitour.com/ o en la oficina del Comité de Golf, Tel. 33 1598 7900 ext. 130 y 158."}', 1, 1)
ON DUPLICATE KEY UPDATE section_type=VALUES(section_type), title=VALUES(title), content=VALUES(content), enabled=1, updated_at=CURRENT_TIMESTAMP;

-- ---------------------------------------------------------------------
-- Elegibilidad (participantes, Copa Challenger, notas, inscripciones)
-- ---------------------------------------------------------------------
INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled) VALUES
(362, 'elegibilidad', 'elegibilidad', 'Elegibilidad',
'{"eligibilityText": "Podrá participar todo golfista amateur mayor de 18 años que cuente con un índice de hándicap registrado en su club o en la Federación Mexicana de Golf, vigente a la fecha de noviembre. Se exceptúa la categoría Campeonato, que requiere hándicap GHIN; en las categorías Campeonato y Damas 1ª también pueden participar jugadoras e invitados mayores de 16 años. Es requisito indispensable acreditar por escrito su constancia de hándicap.", "notesText": ["COPA CHALLENGER: únicamente compiten los jugadores de la categoría CAMPEONATO. Para ganarla deberán ganar tres veces, en forma consecutiva o alternada, los Torneos Anuales del Club de Golf Santa Anita, incluyendo a los juveniles invitados.", "Una vez que exista el ganador de esta V edición de la Copa Challenger, el historial de los anteriores ganadores se elimina y la VI edición se reinicia en 0 (cero).", "Los juveniles invitados en categoría Campeonato deberán firmar carta de renuncia a los premios cuantitativos, sin derecho a rifas, premios de O''Yes ni Hole in One. Participan únicamente por los trofeos de 1°, 2° y 3° lugar, Copa Challenger y los eventos competitivos de Drive, Shoot Out y Putt.", "Marcas de salida: index 0 a 5.1 de azules; 5.2 a 23.8 de blancas; damas de rojas; caballeros mayores de 60 años de doradas; damas mayores de 70 años de rosas; caballeros mayores de 70 años de plateadas.", "SALIDAS: primer turno por horario a partir de las 6:50 a.m.; segundo turno a partir de las 11:00 a.m.", "Los 16 finalistas de las categorías A, B, C, Senior 1ª y Senior 2ª se definen por los scores acumulados de las dos primeras rondas; empate en el lugar 16 se resuelve por sistema. En la categoría D se aplica el mismo criterio con los puntos Stableford.", "En 1ª Damas pasan las mejores 8 (3 gross y 5 netos). En 1ª Senior se toman los 6 mejores gross y los 10 mejores netos.", "Todas las categorías juegan 54 hoyos. Los finalistas juegan el sábado; los jugadores del lugar 17 en adelante juegan según el programa del tercer día asignado.", "Es responsabilidad del jugador verificar y confirmar su horario de salida definitivo antes de cada ronda. Resultados, horarios de salida y premios de O''Yes se publican en la página web del torneo.", "Jugadores foráneos: dos días de práctica una vez pagada la inscripción, en cualquier día de su conveniencia hasta el 7 de noviembre de 2026 (entre semana a cualquier hora, fines de semana después de las 13:00 hrs). Reservaciones con el starter: 33 1598 7900 ext. 130 y 158 (también ext. 127 y 134).", "Socios del Club Santa Anita: dos green fees electrónicos.", "HOTELES SEDE: Hotel Aloft Guadalajara Sur (Av. Paseo Punto Sur 235, Col. Los Gavilanes) alejandra.salinas@aimbridge.com, Tel. 33 4355 0000 / 33 2834 4419 · Hotel Encore, Tel. 33 3898 6000, WhatsApp 33 2804 3508, reservaciones@encoreguadalajara.com · Hotel Microtel, Tel. 33 4077 0303, frontdesk@microtelgdlsur.com"], "inscripcionesText": "Cupo limitado POR CATEGORÍA. Fecha límite de recepción de inscripciones: domingo 1 de noviembre a las 14:00 horas, o antes si la categoría completa su cupo máximo. El costo total debe estar cubierto para respetar el lugar; se dará prioridad a los jugadores con inscripción pagada.\\n\\nInscripciones y reservaciones: https://santaanita.speitour.com/ · Oficina del Comité de Golf · Tel. 33 1598 7900 ext. 130 y 158.\\n\\nPAGO: Club de Golf Santa Anita S.A. de C.V. — BANORTE 0723 2000 6135 2483 42. Indicar nombre completo del jugador.\\nEl pago NO garantiza el lugar: una vez realizado, enviar el comprobante por WhatsApp al 33 1254 6259 con los datos solicitados.\\nFacturación: enviar constancia de situación fiscal el mismo día del pago a Prof. Armando Padilla, Tel. 33 1254 6259. Las facturas deben ser del mismo mes del pago. Correo: comitedegolf@clubdegolfsantanita.com\\n\\nPolítica de cancelación: se reembolsará el pago total o parcial hasta el domingo 4 de octubre; después de esa fecha no habrá devoluciones.\\n\\nAl inscribirse acepta todos los términos y condiciones de esta convocatoria. El Club de Golf Santa Anita se reserva el derecho de admisión."}', 2, 1)
ON DUPLICATE KEY UPDATE section_type=VALUES(section_type), title=VALUES(title), content=VALUES(content), enabled=1, updated_at=CURRENT_TIMESTAMP;

-- ---------------------------------------------------------------------
-- Costos de inscripción (descuento ahora hasta el 30 de septiembre)
-- ---------------------------------------------------------------------
INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled) VALUES
(362, 'costos', 'generic', 'Costos',
'{"sociosPricing": [{"title": "Socios", "caballeros": "12500.00", "damasSeniors": "9500.00"}], "foraneosPricing": [{"title": "No socios", "caballeros": "16500.00", "damasSeniors": "12000.00"}], "pricingNote": "Socios $12,500.00 · Damas socias $9,500.00 · No socios $16,500.00 · Damas no socias $12,000.00. Descuento de $1,000.00 hasta el 30 de septiembre. Plan de pagos disponible para socios, sin descuento.", "inscripcionesText": "INCLUYE: 3 días de competencia; socios 2 green fees y no socios 2 días de práctica; kit de bienvenida; eventos competitivos de Putt, Drive de Distancia y Shoot Out; eventos sociales con acceso a Sala VIP exclusiva para jugadores e invitados (con costo) mediante brazalete; cortesía de alimentos y bebidas en el snack del campo hoyos 5 y 15 y bebidas en los carritos bar; rifas y ceremonia de premiación. El mal uso del brazalete se considera falta al reglamento del club.\\n\\nCOSTO SALA VIP: adultos no jugadores $800.00 por día · menores de edad $400.00 por día."}', 3, 1)
ON DUPLICATE KEY UPDATE section_type=VALUES(section_type), title=VALUES(title), content=VALUES(content), enabled=1, updated_at=CURRENT_TIMESTAMP;

-- ---------------------------------------------------------------------
-- Competencias / premios especiales (O''Yeses, Hole in One, eventos V02)
-- ---------------------------------------------------------------------
INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled) VALUES
(362, 'competencias', 'list', 'Competencias',
'{"items": [{"nombre": "O''YESES — Premio General (hoyos 5, 9, 11 y 15)", "descripcion": "Premio general al 1° y 2° lugar de O''Yes entre todas las categorías.", "premios": "1° Lugar: Automóvil 2026 · 2° Lugar: Carrito de golf (en cada hoyo: 5, 9, 11 y 15)."}, {"nombre": "O''YESES — Rama Damas (hoyos 5, 9, 11 y 15)", "descripcion": "Premios por rama en cada uno de los cuatro hoyos.", "premios": "1° Lugar: Reloj $40,000 · 2° Lugar: Viaje $30,000 · 3° Lugar: Electrónicos $20,000."}, {"nombre": "O''YESES — Rama Seniors (hoyos 5, 9, 11 y 15)", "descripcion": "Premios por rama en cada uno de los cuatro hoyos.", "premios": "1° Lugar: Reloj $40,000 · 2° Lugar: Viaje $30,000 · 3° Lugar: Electrónicos $20,000."}, {"nombre": "O''YESES — Rama Caballeros (hoyos 5, 9, 11 y 15)", "descripcion": "Premios por rama en cada uno de los cuatro hoyos.", "premios": "1° Lugar: Reloj $40,000 · 2° Lugar: Viaje $30,000 · 3° Lugar: Electrónicos $20,000."}, {"nombre": "O''YESES NO REPETIBLES", "descripcion": "Cada participante puede ganar un solo premio de O''Yes, ya sea general o por rama. Si un jugador marca más de un O''Yes se entrega el de mayor valor; a igual valor, el de menor distancia; a igual distancia, el primero en orden cronológico.", "premios": "Los ganadores del Premio General de O''Yes tendrán una retención de impuesto equivalente al 7% del valor del premio recibido."}, {"nombre": "HOLE IN ONE — NO REPETIBLE", "descripcion": "Hoyos 5, 11 o 15: premio adicional exclusivo para el primer y único hoyo en uno del torneo en cualquiera de esos hoyos. Hoyo 9: premio adicional de un carrito de golf Club Car para el primer hoyo en uno. El ganador obtiene el 1° lugar de O''Yes General más el bono con el mismo tiro; un segundo hoyo en uno se considerará para premio de O''Yes, sujeto a las condiciones aplicables.", "premios": "Hoyo 5: O''Yes + $200,000 · Hoyo 11: O''Yes + $200,000 · Hoyo 15: O''Yes + $200,000 · Hoyo 9: O''Yes + Carrito de golf Club Car."}, {"nombre": "TORNEO DE PUTTS — lunes 9 y martes 10", "descripcion": "General y grupos: #1 Campeonato y AA; #2 A y B; #3 C y D; #4 Seniors 1ª y 2ª; #5 Damas 1ª y 2ª. Se publican categoría y horario.", "premios": "General: Putter. Por grupo: 1° Docena de pelotas · 2° Gorra."}, {"nombre": "DRIVE DE DISTANCIA — miércoles 11, a partir de las 19:00 hrs", "descripcion": "Caballeros (general) y grupos: #1 Campeonato y AA; #2 A y B; #3 C y D; #4 Seniors 1ª y 2ª; #5 Damas 1ª y 2ª.", "premios": "Caballeros: 1° Driver · 2° Bolsa de golf. Damas 1ª y 2ª: 1° Driver · 2° Obsequio. Grupos #1 a #4: 1° Docena de pelotas · 2° Obsequio."}, {"nombre": "SHOOT OUT — jueves 12, a partir de las 17:00 hrs", "descripcion": "General y grupos: #1 Campeonato y AA; #2 A y B; #3 C y D; #4 Seniors 1ª y 2ª; #5 Damas 1ª y 2ª.", "premios": "General: 1° 3 wedges · 2° 2 wedges. Por grupo: 1° Docena de pelotas · 2° Obsequio."}, {"nombre": "EVENTOS SOCIALES", "descripcion": "Diario: Sala VIP de 12:00 a 22:00 hrs para jugadores (gratis) y acompañantes ($800 por día), con música en vivo y DJ; rifa al terminar la ronda y actividades con patrocinios.", "premios": "Domingo 8: inauguración y rompehielos, entrega de kit de bienvenida 12:00 a 18:00 hrs. Lunes 9: comida de damas y torneo de Putt. Martes 10: bingo y torneo de Putt. Miércoles 11: Drive de Distancia 19:00 hrs. Jueves 12: Shoot Out 17:00 hrs. Viernes 13: Sala de Despecho a partir de las 19:00 hrs. Sábado 14: clausura, premiación y Gran Rifa."}]}', 4, 1)
ON DUPLICATE KEY UPDATE section_type=VALUES(section_type), title=VALUES(title), content=VALUES(content), enabled=1, updated_at=CURRENT_TIMESTAMP;

-- ---------------------------------------------------------------------
-- Desempates: el corte de 16 finalistas ahora incluye Senior 1ª y 2ª
-- ---------------------------------------------------------------------
INSERT INTO convocatoria_content (torneoid, section_id, section_type, title, content, sort_order, enabled) VALUES
(362, 'desempates', 'desempates', 'Desempates',
'{"intro": "En caso de empate por el 1° lugar de la categoría CAMPEONATO se decidirá por muerte súbita comenzando en el hoyo que el Comité asigne. El 2° y 3° lugar de Campeonato y el 1°, 2° y 3° lugar Gross y Neto de las demás categorías se decidirán por SISTEMA.", "showCorte": true, "showTrofeos": true, "paraCorte": ["Categorías A, B, C, Senior 1ª y Senior 2ª: los 16 finalistas se definen por los scores acumulados de las dos primeras rondas.", "Categoría D: los mejores 16 se definen por los puntos acumulados del sistema Stableford.", "Categoría 1ª Damas: pasan las mejores 8 (3 primeros gross y 5 netos).", "Categoría 1ª Senior: pasan los 6 mejores gross y los 10 mejores netos.", "En caso de empate en el último lugar de clasificación (lugar 16), se desempata por SISTEMA."], "paraTrofeos": ["Campeonato, 1° lugar: muerte súbita a partir del hoyo que el Comité asigne.", "SISTEMA — 1) Suma de los últimos 9 hoyos (10 al 18) de la última tarjeta (tercer día de competencia).", "SISTEMA — 2) Suma de los últimos 6 hoyos (13 al 18).", "SISTEMA — 3) Suma de los últimos 3 hoyos (16 al 18).", "SISTEMA — 4) Score del hoyo 18.", "SISTEMA — 5) Se repite el mismo procedimiento con la vuelta del hoyo 1 al 9.", "SISTEMA — 6) Se aplica el mismo sistema al score del segundo día de competencia.", "SISTEMA — 7) Se aplica el mismo sistema al score del primer día de competencia.", "SISTEMA — 8) De persistir el empate, se decidirá a la suerte (cara o cruz)."], "nota": "El Comité de Golf se reserva el derecho de hacer los cambios necesarios a esta convocatoria que considere pertinentes para el mejor desarrollo del torneo."}', 6, 1)
ON DUPLICATE KEY UPDATE section_type=VALUES(section_type), title=VALUES(title), content=VALUES(content), enabled=1, updated_at=CURRENT_TIMESTAMP;

-- ---------------------------------------------------------------------
-- /reglas — condiciones de competencia: turno de salida 6:50 a.m.
-- ---------------------------------------------------------------------
INSERT INTO convocatoria_content (torneoid, section_id, section_type, content, enabled) VALUES
(362, 'reglas_locales', 'accordion',
'[{"titulo": "Descalificaciones y premios", "contenido": "En caso de descalificación por hándicap índice alterado o cualquier falta al reglamento del club, el jugador pierde todo derecho a cualquier premio que haya obtenido. En caso de descalificación por cualquier otra regla de golf, los premios ya marcados se respetarán."}, {"titulo": "Hora de salida", "contenido": "El jugador deberá iniciar su juego en la hora y grupo establecidos por el Comité. Si llega a su mesa de salida listo para jugar dentro de los 5 minutos siguientes a su hora de salida, podrá jugar con 2 golpes de castigo. Si llega después de los 5 minutos será descalificado."}, {"titulo": "Duda en la aplicación de una regla", "contenido": "En caso de duda en la aplicación de una regla, se jugarán dos bolas, debiendo declarar antes el jugador cuál considera que debe contar, y deberá pedir una decisión al Comité de Reglas antes de firmar su tarjeta."}, {"titulo": "Aparatos electrónicos", "contenido": "Se permite el uso de aparatos electrónicos o digitales que otorguen información sobre distancia."}, {"titulo": "Entrega de score", "contenido": "El jugador(a) es responsable de entregar su tarjeta de score en el área asignada por el Comité inmediatamente después de terminar su ronda, verificar el score de cada hoyo y aclarar cualquier duda con el Comité Organizador, asegurándose de que esté firmada por el jugador y por su anotador. La tarjeta debe entregarse a más tardar 30 minutos después de haber salido del campo. La infracción a esta regla se sancionará con la regla correspondiente."}, {"titulo": "Carritos de golf y vestimenta", "contenido": "Con excepción de la categoría Campeonato, se permite el uso de carrito de golf. Se prohíbe el uso de pantalones de mezclilla y toda vestimenta fuera de los protocolos de la etiqueta del golf durante el juego."}, {"titulo": "Salidas", "contenido": "Primer turno por horario a partir de las 6:50 a.m. y segundo turno a partir de las 11:00 a.m. Es responsabilidad del jugador verificar y confirmar su horario de salida definitivo antes de cada ronda."}]', 1)
ON DUPLICATE KEY UPDATE section_type=VALUES(section_type), content=VALUES(content), enabled=1, updated_at=CURRENT_TIMESTAMP;

COMMIT;
